use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_trivia::CommentRanges;
use ruff_source_file::LineRanges;
use ruff_text_size::{TextRange, TextSize};

use crate::settings::LinterSettings;
use crate::Locator;

use super::super::detection::comment_contains_code;

/// ## What it does
/// Checks for commented-out Python code.
///
/// ## Why is this bad?
/// Commented-out code is dead code, and is often included inadvertently.
/// It should be removed.
///
/// ## Known problems
/// Prone to false positives when checking comments that resemble Python code,
/// but are not actually Python code ([#4845]).
///
/// ## Example
/// ```python
/// # print("Hello, world!")
/// ```
///
/// ## Options
/// - `lint.task-tags`
///
/// [#4845]: https://github.com/astral-sh/ruff/issues/4845
#[derive(ViolationMetadata)]
pub(crate) struct CommentedOutCode;

impl Violation for CommentedOutCode {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::None;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Found commented-out code".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove commented-out code".to_string())
    }
}

/// ERA001
pub(crate) fn commented_out_code(
    diagnostics: &mut Vec<Diagnostic>,
    locator: &Locator,
    comment_ranges: &CommentRanges,
    settings: &LinterSettings,
) {
    let mut comments = comment_ranges.into_iter().peekable();
    // Iterate over all comments in the document.
    while let Some(range) = comments.next() {
        let line = locator.line_str(range.start());

        if is_script_tag_start(line) {
            if skip_script_comments(range, &mut comments, locator) {
                continue;
            }
        }

        // Verify that the comment is on its own line, and that it contains code.
        if is_own_line_comment(line) && comment_contains_code(line, &settings.task_tags[..]) {
            let mut diagnostic = Diagnostic::new(CommentedOutCode, range);
            diagnostic.set_fix(Fix::display_only_edit(Edit::range_deletion(
                locator.full_lines_range(range),
            )));
            diagnostics.push(diagnostic);
        }
    }
}

/// Parses the rest of a [PEP 723](https://peps.python.org/pep-0723/)
/// script comment and moves `comments` past the script comment's end unless
/// the script comment is invalid.
///
/// Returns `true` if it is a valid script comment.
fn skip_script_comments<I>(
    script_start: TextRange,
    comments: &mut std::iter::Peekable<I>,
    locator: &Locator,
) -> bool
where
    I: Iterator<Item = TextRange>,
{
    let source = locator.contents();
    let opener = locator.line_str(script_start.start());
    let opener_is_script;
    if opener.is_empty() {
        opener_is_script = false;
    } else {
        let opener_bytes = opener.as_bytes();
        if opener_bytes.len() != 12 {
            opener_is_script = false;
        } else if opener_bytes[0] != b'#' {
            opener_is_script = false;
        } else if opener_bytes[1] != b' ' {
            opener_is_script = false;
        } else if opener_bytes[2] != b'/' {
            opener_is_script = false;
        } else if opener_bytes[3] != b'/' {
            opener_is_script = false;
        } else if opener_bytes[4] != b'/' {
            opener_is_script = false;
        } else if opener_bytes[5] != b' ' {
            opener_is_script = false;
        } else if opener_bytes[6] != b's' {
            opener_is_script = false;
        } else if opener_bytes[7] != b'c' {
            opener_is_script = false;
        } else if opener_bytes[8] != b'r' {
            opener_is_script = false;
        } else if opener_bytes[9] != b'i' {
            opener_is_script = false;
        } else if opener_bytes[10] != b'p' {
            opener_is_script = false;
        } else if opener_bytes[11] != b't' {
            opener_is_script = false;
        } else {
            opener_is_script = true;
        }
    }
    if !opener_is_script {
        return false;
    }

    let start_index = usize::from(script_start.end());
    let source_len = source.len();
    let source_bytes = source.as_bytes();
    let mut line_end = TextSize::try_from(source_len).unwrap_or_default();
    if start_index < source_len {
        let mut cursor = start_index;
        let mut found_line_break = false;
        while cursor < source_len {
            let current = source_bytes[cursor];
            if current == b'\n' {
                let next_index = cursor + 1;
                if let Ok(converted) = TextSize::try_from(next_index) {
                    line_end = converted;
                    found_line_break = true;
                }
                break;
            } else if current == b'\r' {
                if cursor + 1 < source_len {
                    if source_bytes[cursor + 1] == b'\n' {
                        let next_index = cursor + 2;
                        if let Ok(converted) = TextSize::try_from(next_index) {
                            line_end = converted;
                            found_line_break = true;
                        }
                        break;
                    }
                    let next_index = cursor + 1;
                    if let Ok(converted) = TextSize::try_from(next_index) {
                        line_end = converted;
                        found_line_break = true;
                    }
                    break;
                }
                let next_index = cursor + 1;
                if let Ok(converted) = TextSize::try_from(next_index) {
                    line_end = converted;
                    found_line_break = true;
                }
                break;
            } else {
                cursor += 1;
            }
        }
        if !found_line_break {
            if let Ok(converted) = TextSize::try_from(source_len) {
                line_end = converted;
            }
        }
    } else if source_len == 0 {
        line_end = TextSize::from(0);
    }

    let mut offset = line_end;
    let mut end_offset: Option<TextSize> = None;

    loop {
        let index = usize::from(offset);
        if index >= source_len {
            break;
        }
        let rest = &source[index..];
        if rest.is_empty() {
            break;
        }

        let rest_bytes = rest.as_bytes();
        let mut newline_at = None;
        let mut newline_width = 0usize;
        let mut search = 0usize;
        while search < rest_bytes.len() {
            let byte = rest_bytes[search];
            if byte == b'\n' {
                newline_at = Some(search);
                newline_width = 1;
                break;
            }
            if byte == b'\r' {
                if search + 1 < rest_bytes.len() {
                    if rest_bytes[search + 1] == b'\n' {
                        newline_at = Some(search);
                        newline_width = 2;
                        break;
                    }
                    newline_at = Some(search);
                    newline_width = 1;
                    break;
                }
                newline_at = Some(search);
                newline_width = 1;
                break;
            }
            search += 1;
        }

        let (line_text, line_full_end, next_offset) = if let Some(position) = newline_at {
            let full_width = position + newline_width;
            let text = &rest[..position];
            let full_end = offset + TextSize::try_from(full_width).unwrap_or_default();
            (text, full_end, full_end)
        } else {
            let full_end = TextSize::try_from(source_len).unwrap_or(offset);
            (rest, full_end, full_end)
        };

        let valid_content: Option<&str>;
        if line_text.is_empty() {
            valid_content = None;
        } else {
            let mut chars = line_text.chars();
            if let Some(first) = chars.next() {
                if first == '#' {
                    if let Some(second) = chars.next() {
                        if second == ' ' {
                            valid_content = Some(chars.as_str());
                        } else if second == '\t' {
                            valid_content = None;
                        } else {
                            valid_content = None;
                        }
                    } else {
                        valid_content = Some("");
                    }
                } else if first == ' ' {
                    valid_content = None;
                } else if first == '\t' {
                    valid_content = None;
                } else {
                    valid_content = None;
                }
            } else {
                valid_content = None;
            }
        }

        let Some(content) = valid_content else {
            break;
        };

        let mut is_terminator = false;
        if content.len() == 3 {
            let mut slashes = content.chars();
            if let Some(first_slash) = slashes.next() {
                if first_slash == '/' {
                    if let Some(second_slash) = slashes.next() {
                        if second_slash == '/' {
                            if let Some(third_slash) = slashes.next() {
                                if third_slash == '/' && slashes.next().is_none() {
                                    is_terminator = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        if is_terminator {
            let lookahead_index = usize::from(next_offset);
            let mut lookahead_is_embedded_line = false;
            let mut lookahead_end = next_offset;
            if lookahead_index < source_len && !source[lookahead_index..].is_empty() {
                let lookahead_rest = &source[lookahead_index..];
                let lookahead_bytes = lookahead_rest.as_bytes();
                let mut look_nl_at = None;
                let mut look_nl_width = 0usize;
                let mut look_search = 0usize;
                while look_search < lookahead_bytes.len() {
                    let look_byte = lookahead_bytes[look_search];
                    if look_byte == b'\n' {
                        look_nl_at = Some(look_search);
                        look_nl_width = 1;
                        break;
                    }
                    if look_byte == b'\r' {
                        if look_search + 1 < lookahead_bytes.len() {
                            if lookahead_bytes[look_search + 1] == b'\n' {
                                look_nl_at = Some(look_search);
                                look_nl_width = 2;
                                break;
                            }
                            look_nl_at = Some(look_search);
                            look_nl_width = 1;
                            break;
                        }
                        look_nl_at = Some(look_search);
                        look_nl_width = 1;
                        break;
                    }
                    look_search += 1;
                }

                let (look_text, look_full_end) = if let Some(position) = look_nl_at {
                    let full_width = position + look_nl_width;
                    let text = &lookahead_rest[..position];
                    let full_end = next_offset + TextSize::try_from(full_width).unwrap_or_default();
                    (text, full_end)
                } else {
                    let full_end = TextSize::try_from(source_len).unwrap_or(next_offset);
                    (lookahead_rest, full_end)
                };
                lookahead_end = look_full_end;

                if look_text.is_empty() {
                    lookahead_is_embedded_line = false;
                } else {
                    let mut look_chars = look_text.chars();
                    if let Some(look_first) = look_chars.next() {
                        if look_first == '#' {
                            if let Some(look_second) = look_chars.next() {
                                lookahead_is_embedded_line = look_second == ' ';
                            } else {
                                lookahead_is_embedded_line = true;
                            }
                        } else if look_first == ' ' {
                            lookahead_is_embedded_line = false;
                        } else if look_first == '\t' {
                            lookahead_is_embedded_line = false;
                        } else {
                            lookahead_is_embedded_line = false;
                        }
                    } else {
                        lookahead_is_embedded_line = false;
                    }
                }
            }

            if lookahead_is_embedded_line {
                offset = lookahead_end;
                continue;
            }
            end_offset = Some(line_full_end);
            break;
        }

        offset = next_offset;
    }

    let Some(end_offset) = end_offset else {
        return false;
    };

    while let Some(comment) = comments.peek() {
        let comment_start = comment.start();
        let comment_end = comment.end();
        if comment_start >= end_offset {
            break;
        }
        if comment_end <= comment_start {
            comments.next();
            continue;
        }
        if comment_start < line_end && comment_end <= line_end {
            comments.next();
            continue;
        }
        comments.next();
    }

    true
}

/// Returns `true` if line contains an own-line comment.
fn is_own_line_comment(line: &str) -> bool {
    for char in line.chars() {
        if char == '#' {
            return true;
        }
        if !char.is_whitespace() {
            return false;
        }
    }
    unreachable!("Comment should contain '#' character")
}

/// Returns `true` if the line appears to start a script tag.
///
/// See: <https://peps.python.org/pep-0723/>
fn is_script_tag_start(line: &str) -> bool {
    line == "# /// script"
}

#[cfg(test)]
mod tests {
    use ruff_python_parser::parse_module;
    use ruff_python_trivia::CommentRanges;
    use ruff_source_file::LineRanges;
    use ruff_text_size::TextSize;

    use crate::rules::eradicate::rules::commented_out_code::skip_script_comments;
    use crate::Locator;

    #[test]
    fn script_comment() {
        let code = r#"
# /// script
# requires-python = ">=3.11"
# dependencies = [
#   "requests<3",
#   "rich",
# ]
# ///

a = 10 # abc
        "#;

        let parsed = parse_module(code).unwrap();
        let locator = Locator::new(code);

        let comments = CommentRanges::from(parsed.tokens());
        let mut comments = comments.into_iter().peekable();

        let script_start = code.find("# /// script").unwrap();
        let script_start_range = locator.full_line_range(TextSize::try_from(script_start).unwrap());

        let valid = skip_script_comments(script_start_range, &mut comments, &Locator::new(code));

        assert!(valid);

        let next_comment = comments.next();

        assert!(next_comment.is_some());
        assert_eq!(&code[next_comment.unwrap()], "# abc");
    }

    #[test]
    fn script_comment_end_precedence() {
        let code = r#"
# /// script
# [tool.uv]
# extra-index-url = ["https://pypi.org/simple", """\
# https://example.com/
# ///
# """
# ]
# ///

a = 10 # abc
        "#;

        let parsed = parse_module(code).unwrap();
        let locator = Locator::new(code);

        let comments = CommentRanges::from(parsed.tokens());
        let mut comments = comments.into_iter().peekable();

        let script_start = code.find("# /// script").unwrap();
        let script_start_range = locator.full_line_range(TextSize::try_from(script_start).unwrap());

        let valid = skip_script_comments(script_start_range, &mut comments, &Locator::new(code));

        assert!(valid);

        let next_comment = comments.next();

        assert!(next_comment.is_some());
        assert_eq!(&code[next_comment.unwrap()], "# abc");
    }
}

